import ast, os, collections
orig = ast.parse(open('/tmp/reports_orig.py', encoding='utf-8').read())
def tops(tree):
    out=[]
    for n in tree.body:
        if isinstance(n,(ast.FunctionDef,ast.ClassDef)): out.append(n.name)
        elif isinstance(n,ast.Assign):
            for t in n.targets:
                if isinstance(t,ast.Name): out.append(t.id)
        elif isinstance(n,ast.AnnAssign) and isinstance(n.target,ast.Name): out.append(n.target.id)
    return out
pub=[n for n in tops(orig) if not n.startswith('_') and n!='__all__']
allnames=[ast.literal_eval(n.value) for n in orig.body if isinstance(n,ast.Assign) and getattr(n.targets[0],'id','')=='__all__'][0]
home={}
root='tally/reports'
for d,_,fs in os.walk(root):
    for f in fs:
        if not f.endswith('.py') or f=='__init__.py': continue
        p=os.path.join(d,f); mod='.'+os.path.relpath(p,root)[:-3].replace(os.sep,'.')
        for n in tops(ast.parse(open(p,encoding='utf-8').read())):
            home.setdefault(n,[]).append(mod)
by=collections.defaultdict(list)
for n in pub:
    assert len(home[n])==1,(n,home.get(n))
    by[home[n][0]].append(n)
doc=ast.get_docstring(orig,clean=False)
lines=['"""'+doc+'"""','','from __future__ import annotations','']
for mod in sorted(by, key=lambda m:(m.count('.'),m)):
    lines.append(f'from {mod} import (')
    lines += [f'    {n},' for n in by[mod]]
    lines.append(')')
lines.append('from . import renderers  # noqa: F401  (registers every renderer and alias)')
lines.append('')
lines.append('__all__ = [')
lines += [f'    "{n}",' for n in allnames]
lines.append(']')
open('tally/reports/__init__.py','w',encoding='utf-8').write('\n'.join(lines)+'\n')
print(len(pub))
