import ast, os, sys, importlib, inspect, types, subprocess, json
root='tally/reports'
mods={}
for d,_,fs in os.walk(root):
    for f in fs:
        if f.endswith('.py'):
            p=os.path.join(d,f); n=os.path.relpath(p,'.')[:-3].replace(os.sep,'.')
            if n.endswith('.__init__'): n=n[:-9]
            mods[n]=p
    for f in fs:
        if f.endswith('.py') and sum(1 for _ in open(os.path.join(d,f)))>400: print('TOO LONG',d,f)
def layer(n):
    parts=n.split('.')
    if len(parts)==2: return 6
    t=parts[2]
    return {'errors':0,'tables':0,'state':0,'system':0,'formatting':1,'model':1,'loading':2,'aggregate':3,'renderers':4,'cli':5}[t]
edges={}
for n,p in mods.items():
    tree=ast.parse(open(p,encoding='utf-8').read())
    pkg=n if p.endswith('__init__.py') else n.rsplit('.',1)[0]
    es=set()
    for node in ast.walk(tree):
        if isinstance(node,ast.Import):
            for a in node.names: es.add(a.name)
        elif isinstance(node,ast.ImportFrom):
            if node.level:
                base=pkg.split('.')
                base=base[:len(base)-(node.level-1)]
                b='.'.join(base+([node.module] if node.module else []))
            else: b=node.module
            for a in node.names:
                c=b+'.'+a.name
                es.add(c if c in mods else b)
    edges[n]=es
    for e in es:
        if e.startswith('tally') and not e.startswith('tally.reports'): print('NOT SELF-CONTAINED',n,e)
        if e in mods and e!='tally.reports' and layer(e)>layer(n): print('LAYER',n,e)
        if e=='tally.reports': print('IMPORTS PACKAGE',n)
# cycles
color={}
def dfs(u,st):
    color[u]=1
    for v in edges.get(u,()):
        if v not in mods or v==u: continue
        if color.get(v)==1: print('CYCLE',st+[v])
        elif v not in color: dfs(v,st+[v])
    color[u]=2
for m in mods: 
    if m not in color: dfs(m,[m])
